   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "amount",
   "type": "number",
   "required": true,
   "description": "The amount of the payment.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from splitwise app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "group_id",
   "type": "integer",
   "required": false,
   "description": "The ID of the group to record the payment in.",
   "default": null,
   "constraints": []
